sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var message = '';

  switch (newValue) {
    case 'excellent':
      message = 'Thank you! We’re thrilled you loved it!';
      break;
    case 'good':
      message = 'Thank you! Glad you had a good experience.';
      break;
    case 'average':
      message = 'Thank you for your feedback!';
      break;
    case 'poor':
      message = 'Thank you for your feedback. We’re sorry your experience was poor.';
      break;
    default:
      message = 'Thank you for your feedback!';
  }

  g_form.showFieldMsg('x_rating', message, 'info');

}
